package com.bank.treasury.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Shortest run of consecutive days whose inflows reach at least the target.
// Inflows are positive, which is what makes the greedy window correct.
public class LiquidityCertifier {
    private static final Logger log = Logger.getLogger(LiquidityCertifier.class.getName());

    public int shortestDaysToReach(int[] dailyInflows, int target) {
        if (dailyInflows == null || dailyInflows.length == 0) {
            return 0;
        }
        int left = 0;
        long sum = 0;
        int best = Integer.MAX_VALUE;

        for (int right = 0; right < dailyInflows.length; right++) {
            sum += dailyInflows[right]; // expand: add today's inflow
            // Shrink while we still meet the target, to find the shortest span.
            while (sum >= target) {
                best = Math.min(best, right - left + 1);
                sum -= dailyInflows[left];
                final int ls = left;
                final int cur = best;
                log.fine(() -> "Target met; shrinking from left " + ls + "; best=" + cur);
                left++;
            }
        }
        int result = (best == Integer.MAX_VALUE) ? 0 : best;
        final int r = result;
        log.info(() -> "Shortest days to reach " + target + " over "
                + Arrays.toString(dailyInflows) + " = " + r);
        return result;
    }
}
